import React from "react";

export default function About() {
  return (
    <div className="about-page">

      <div className="about-wrapper">

        {/* LEFT SIDE */}
        <div className="about-left">

          {/* ABOUT ME (moved slightly aligned visually) */}
          <div className="about-top">
            <h1>
              About <span>Me</span>
            </h1>

            <p>
              I am an Information Technology student with a strong interest in using technology to solve real-world problems. I enjoy exploring ideas, understanding how systems work, and transforming concepts into practical and efficient solutions. Through academic projects, internships, and technical events, I have gained hands-on experience that has strengthened my problem-solving abilities and teamwork skills. These experiences have helped me appreciate the importance of building reliable, user-focused applications. I am adaptable, eager to learn, and committed to continuously improving my technical and professional capabilities. I take initiative, learn from challenges, and strive to grow into a capable and responsible developer.
            </p>
          </div>

          {/* WHAT I DO */}
          <div className="what-i-do">
            <h3>🚀 What I Do</h3>

            <p>
              I approach development by analyzing problems in a structured way and breaking them into smaller, manageable components. I focus on building solutions step by step, ensuring that the final output is clean, functional, and easy to use. Much of my learning comes through hands-on project work, where I understand how different parts of a system interact and contribute to a complete and efficient application.
            </p>

          </div>

        </div>

        {/* RIGHT SIDE */}
        <div className="about-right">

          {/* EDUCATION */}
          <div className="card education-card">
            <div className="card-header">
              <h3>🎓 Education</h3>
              <span className="year">2023–2027</span>
            </div>

            <p><strong>B.Tech – Information Technology</strong></p>
            <p className="college">Panimalar Engineering College</p>

            <p>
              My academic studies are focused on Information Technology, where I am developing a strong understanding of programming, database systems, and software engineering principles. Along with theoretical knowledge, I actively apply concepts through practical assignments and projects.
            </p>
          </div>

          {/* INTERESTS */}
          <div className="card">
            <h3>💡 Interests</h3>

            <div className="tags">
              <span>Java</span>
              <span>Full Stack Development</span>
              <span>Data Analytics</span>
              <span>DBMS</span>
              <span>UI/UX</span>
              <span>AI</span>
            </div>
          </div>

        </div>

      </div>

      {/* STATS */}
      <div className="stats">
        <div className="stat-box">
          <h3>5+</h3>
          <p>Projects</p>
        </div>
        <div className="stat-box">
          <h3>10+</h3>
          <p>Technologies</p>
        </div>
        <div className="stat-box">
          <h3>2+</h3>
          <p>Domains</p>
        </div>
      </div>

      <style>{`

        .about-page {
          min-height: 100vh;
          padding: 60px 10%;
          font-family: "Poppins", sans-serif;
          background: #0f172a;
          color: white;
        }

        .about-wrapper {
          display: grid;
          grid-template-columns: 1.2fr 1fr;
          gap: 50px;
          align-items: start;
        }

        /* LEFT */
        .about-left h1 {
          font-size: 42px;
          margin-bottom: 12px;
        }

        .about-left span {
          color: #38BDF8;
        }

        .about-left p {
          color: #cbd5e1;
          line-height: 1.8;
          margin-bottom: 10px;
        }

        /* WHAT I DO */
        .what-i-do {
          margin-top: 18px;
          padding: 18px;
          border-radius: 10px;
          background: rgba(255,255,255,0.05);
          border-left: 4px solid #38BDF8;
        }

        .what-i-do h3 {
          margin-bottom: 8px;
          color: #38BDF8;
        }

        /* RIGHT SIDE */
        .about-right {
          display: flex;
          flex-direction: column;
          gap: 18px;
          margin-top: -10px; /* 🔥 moves education slightly upward */
        }

        .card {
          background: rgba(255,255,255,0.05);
          padding: 22px;
          border-radius: 14px;
          border: 1px solid rgba(56,189,248,0.2);
          transition: 0.3s;
        }

        .card:hover {
          transform: translateY(-5px);
          box-shadow: 0 0 20px rgba(56,189,248,0.4);
        }

        .card h3 {
          margin-bottom: 8px;
          color: #38BDF8;
        }

        .card p {
          color: #cbd5e1;
          font-size: 15px;
          line-height: 1.6;
        }

        .education-card {
          margin-top: -5px;
        }

        /* HEADER */
        .card-header {
          display: flex;
          justify-content: space-between;
          align-items: center;
          margin-bottom: 6px;
        }

        .year {
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
          padding: 2px 8px;
          border-radius: 8px;
          font-size: 10px;
          font-weight: 600;
        }

        .college {
          color: #7dd3fc;
          font-weight: 500;
        }

        /* INTEREST TAGS */
        .tags {
          display: flex;
          flex-wrap: wrap;
          gap: 8px;
          margin-top: 10px;
        }

        .tags span {
          background: rgba(56,189,248,0.15);
          color: #38BDF8;
          padding: 5px 10px;
          border-radius: 20px;
          font-size: 12px;
        }

        /* STATS */
        .stats {
          display: flex;
          gap: 20px;
          margin-top: 40px;
        }

        .stat-box {
          flex: 1;
          text-align: center;
          padding: 15px;
          border-radius: 10px;
          background: rgba(255,255,255,0.05);
        }

        .stat-box h3 {
          color: #38BDF8;
        }

        /* MOBILE */
        @media (max-width: 900px) {
          .about-wrapper {
            grid-template-columns: 1fr;
          }

          .stats {
            flex-direction: column;
          }

          .about-right {
            margin-top: 0;
          }
        }

      `}</style>

    </div>
  );
}
